// astera supports running jobs on the Astera Kubernetes cluster, through
// the actl Queue (https://actl.astera.sh): each simmer job is a Queue
// Entry, which is an Indexed Job scheduled by KAI, with one worker per
// run ([JobParams.NRuns]), each running job.sbatch with its run number.
// actl uploads the job directory as the source of the Entry, into its
// workspace. Everything else is as for the Kube server (kube.go): the
// worker script, the results on the shared volume, and the helper pod
// for the status files and the results.

// asteraEnv sets KUBECONFIG to the actl one (~/.kube/astera-sh-oidc.yaml)
// if it is not set, for kubectl.
func asteraEnv() {
	if os.Getenv("KUBECONFIG") != "" {
		return
	}
	if home, err := os.UserHomeDir(); err == nil {
		kc := filepath.Join(home, ".kube", "astera-sh-oidc.yaml")
		if goalib.FileExists(kc) {
			os.Setenv("KUBECONFIG", kc)
		}
	}
}

// asteraScheduling returns the node selector and tolerations of the helper
// pod: the shared (NFS) volumes mount only on the GPU nodes of the pool
// ([KubeParams.Pool], vp by default) of the namespace, which have its
// labels and taints. The workers are scheduled by actl.
func (sr *Simmer) asteraScheduling() (map[string]string, []string) {
	pool := sr.Project.Server.K8s.Pool
	if pool == "" {
		pool = "vp"
	}
	sel := map[string]string{
		"astera.org/pool":                     pool,
		"astera.org/ns-" + sr.kubeNamespace(): "true",
	}
	return sel, []string{"nvidia.com/gpu", "astera.org/namespace"}
}

// asteraActl runs the given actl command in the namespace of the jobs,
// returning its output. Its input is empty: it must not prompt.
func (sr *Simmer) asteraActl(args ...string) (string, error) {
	sr.kubeEnv()
	ns := sr.kubeNamespace()
	out := goalrun.Output("actl", args, "-n", ns, "--no-color", "<", "/dev/null")
	return out, goalError()
}

// WriteAsteraQueue writes the actl-queue.yaml file of the job's Entry.
func (sr *Simmer) WriteAsteraQueue(w io.Writer, jid string) {
	pr := sr.Project
	k := &pr.Server.K8s
	cpus := max(pr.Job.CPUsPerTask, 1)
	fmt.Fprintf(w, "# actl Queue Entry for simmer job %s (see https://actl.astera.sh)\n", jid)
	fmt.Fprintf(w, "name: %s\n", sr.kubeJobName(jid))
	fmt.Fprintf(w, "image: %s\n", k.Image)
	if k.Pool != "" {
		fmt.Fprintf(w, "pool: %s\n", k.Pool)
	}
	if k.Queue != "" {
		fmt.Fprintf(w, "queue: %s\n", k.Queue)
	}
	fmt.Fprintf(w, "project:\n  path: .\n")
	fmt.Fprintf(w, "resources:\n")
	fmt.Fprintf(w, "  replicas: %d\n", max(pr.Job.NRuns, 1))
	fmt.Fprintf(w, "  gpu: %d\n", max(pr.Job.GPUs, 0))
	fmt.Fprintf(w, "  cpu: \"%d\"\n", cpus)
	fmt.Fprintf(w, "  memory: %dGi\n", max(pr.Job.Memory, 1)*cpus)
	fmt.Fprintf(w, "volumes:\n")
	fmt.Fprintf(w, "  - name: shared\n    pvc: %s\n    mountPath: %s\n", sr.kubePVC(), sr.kubeMount())
	fmt.Fprintf(w, "env:\n")
	fmt.Fprintf(w, "  NVIDIA_DRIVER_CAPABILITIES: all # graphics, for Vulkan\n")
	fmt.Fprintf(w, "  SIMMER_JOB: %s\n", jid)
	fmt.Fprintf(w, "command: [bash, job.sbatch]\n")
}

// SubmitAstera submits the given job as an actl Queue Entry, from its
// local job directory, which is the current one after, returning its name.
func (sr *Simmer) SubmitAstera(jid, args string) string {
	entry, err := sr.asteraSubmit(jid, args)
	if err != nil {
		core.ErrorSnackbar(sr, err)
		return ""
	}
	sr.GetMeta(jid)
	return entry
}

// asteraSubmit writes the job files and submits the Entry of the given
// job, from its local job directory, returning the name of the Entry,
// which it also writes to job.job.
func (sr *Simmer) asteraSubmit(jid, args string) (string, error) {
	sr.kubeStart()
	if err := sr.kubeWriteJobFiles(jid, args); err != nil {
		return "", err
	}
	var b bytes.Buffer
	sr.WriteAsteraQueue(&b, jid)
	if err := os.WriteFile("actl-queue.yaml", b.Bytes(), 0644); err != nil {
		return "", err
	}
	out := goalrun.Output("actl", sr.asteraSubmitArgs(false), "<", "/dev/null")
	fmt.Println(out)
	if err := goalError(); err != nil {
		return "", err
	}
	// --no-attach prints the name of the Entry
	prefix := sr.kubeJobName(jid)
	entry := asteraEntryName(out, prefix)
	if entry == "" { // look it up
		list, _ := sr.asteraActl("queue", "list")
		entry = asteraEntryName(list, prefix)
	}
	goalib.WriteFile("job.job", entry)
	if entry == "" {
		return "", fmt.Errorf("Submitted job %s, but could not find the name of its Entry in the output of actl queue submit", jid)
	}
	return entry, nil
}

// asteraSubmitArgs returns the actl arguments to submit the Entry of the
// job in the current directory, as a dry run if dryRun.
func (sr *Simmer) asteraSubmitArgs(dryRun bool) []string {
	args := []string{"queue", "submit", "--no-attach", "-f", "actl-queue.yaml", "-n", sr.kubeNamespace(), "--no-color"}
	if dryRun {
		args = append(args, "--dry-run")
	}
	if sa := sr.Project.Server.K8s.ServiceAccount; sa != "" {
		args = append(args, "--service-account", sa)
	}
	return args
}

// asteraEntryName returns the name of the Entry with the given prefix
// in the given actl output, which is the last one, or "".
func asteraEntryName(out, prefix string) string {
	name := ""
	for _, f := range strings.FieldsFunc(out, func(r rune) bool {
		return !(r == '-' || r == '.' || r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	}) {
		if strings.HasPrefix(f, prefix) {
			name = strings.Trim(f, ".")
		}
	}
	return name
}

// JobStatusAstera updates the status of the given job, in the current
// (local job) directory, returning it (see [Simmer.kubeRunsStatus]), with
// the status of its Entry from actl in job.squeue, as its ServerStatus.
func (sr *Simmer) JobStatusAstera(jid string) string {
	sr.kubeStart()
	if entry := strings.TrimSpace(goalib.ReadFile("job.job")); entry != "" {
		ns := sr.kubeNamespace()
		st := goalrun.OutputErrOK("actl", "queue", "status", entry, "-n", ns, "--no-color", "<", "/dev/null")
		goalib.WriteFile("job.squeue", strings.Join(strings.Fields(st), " "))
	}
	return sr.kubeRunsStatus(jid)
}

// CancelJobsAstera cancels the given jobs, by deleting their Entries.
// Their results on the shared volume are kept.
func (sr *Simmer) CancelJobsAstera(jobs []string) error {
	var errs []error
	ns := sr.kubeNamespace()
	for _, jid := range jobs {
		sr.kubeStart() // each job is independent
		entry := sr.ValueForJob(jid, "ServerJob")
		if entry == "" {
			continue
		}
		goalrun.Run("actl", "queue", "delete", entry, "-n", ns, "--yes", "--no-color", "<", "/dev/null")
		if err := goalError(); err != nil {
			errs = append(errs, err)
			continue
		}
		goalib.WriteFile(filepath.Join(sr.JobPath(jid), "job.status"), "Canceled")
		sr.GetMeta(jid)
	}
	return errors.Join(errs...)
}

// DeleteJobsAstera deletes the given jobs: their Entries (with their
// uploaded source), and their results directories on the shared volume.
func (sr *Simmer) DeleteJobsAstera(jobs []string) error {
	var errs []error
	ns := sr.kubeNamespace()
	for _, jid := range jobs {
		sr.kubeStart() // each job is independent
		if entry := sr.ValueForJob(jid, "ServerJob"); entry != "" {
			goalrun.RunErrOK("actl", "queue", "delete", entry, "-n", ns, "--yes", "--no-color", "<", "/dev/null")
		}
		if err := sr.kubeDeleteResults(jid); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

// QueueAstera shows the Entries of the user and the pools of the namespace,
// with the load of the queue: the Entries of all users in the namespace,
// the resources allocated and requested in the KAI queue of the namespace
// and that of its pool (all the queues in it), and the free resources of
// the nodes of the namespace (with the workspace pods, which are not in
// the queue).
func (sr *Simmer) QueueAstera() {
	sr.kubeStart()
	ts := sr.Tabs.AsLab()
	ns := sr.kubeNamespace()
	pool := sr.Project.Server.K8s.Pool
	if pool == "" {
		pool = "vp"
	}
	queue := sr.Project.Server.K8s.Queue
	if queue == "" {
		queue = ns + "-" + pool
	}
	jp := `jsonpath={range .items[*]}{.metadata.name}{"\t"}{.status.allocated}{"\t"}{.status.requested}{"\n"}{end}`
	list := goalrun.OutputErrOK("actl", "queue", "list", "-n", ns, "--no-color", "<", "/dev/null")
	pools := goalrun.OutputErrOK("actl", "queue", "pools", "-n", ns, "--no-color", "<", "/dev/null")
	all := goalrun.OutputErrOK("actl", "queue", "list", "-A", "-n", ns, "--no-color", "<", "/dev/null")
	kai := goalrun.OutputErrOK("kubectl", "get", "queues.scheduling.run.ai", queue, pool, "-o", jp, "<", "/dev/null")
	nodes := goalrun.OutputErrOK("actl", "pod", "profiles", "--by-node", "-n", ns, "--no-color", "<", "/dev/null")
	sep := "\n" + strings.Repeat("#", 60) + "\n"
	out := list + sep + pools + sep
	out += "Entries of all users:\n" + all + sep
	out += "KAI queues: allocated, requested:\n" + kai + sep
	out += "Nodes:\n" + nodes + "\n" + time.Now().Format(sr.Project.TimeFormat)
	ts.EditorString("Queue", out)
}
